      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"20\" y=\"25\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">MATRIZ COMPARATIVA DE LA FAMILIA ANTHROPIC CLAUDE</text>\n  <text x=\"440\" y=\"25\" fill=\"#94a3b8\" font-size=\"9\">Ventana contextual estándar: 200.000 tokens</text>\n\n  <!-- Model 1: Haiku 3.5 -->\n  <g transform=\"translate(15, 38)\">\n    <rect width=\"205\" height=\"180\" rx=\"6\" fill=\"#111c33\" stroke=\"#34d399\" stroke-width=\"1.5\"/>\n    <rect width=\"205\" height=\"26\" rx=\"6\" fill=\"#064e3b\"/>\n    <text x=\"12\" y=\"17\" fill=\"#a7f3d0\" font-size=\"10\" font-weight=\"800\">CLAUDE 3.5 HAIKU</text>\n    <text x=\"135\" y=\"17\" fill=\"#6ee7b7\" font-size=\"8.5\" font-weight=\"700\">Baja Latencia</text>\n\n    <text x=\"12\" y=\"42\" fill=\"#cbd5e1\" font-size=\"8.5\" font-weight=\"700\">Métricas Clave:</text>\n    <text x=\"12\" y=\"56\" fill=\"#94a3b8\" font-size=\"8\">• TTFT líder: &lt; 250 ms</text>\n    <text x=\"12\" y=\"70\" fill=\"#94a3b8\" font-size=\"8\">• Salida máxima: 8.192 tokens</text>\n    <text x=\"12\" y=\"84\" fill=\"#94a3b8\" font-size=\"8\">• Coste: Fracción de Sonnet</text>\n\n    <rect x=\"10\" y=\"96\" width=\"185\" height=\"74\" rx=\"4\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"16\" y=\"110\" fill=\"#34d399\" font-size=\"8\" font-weight=\"700\">Casos de Uso Ideales:</text>\n    <text x=\"16\" y=\"124\" fill=\"#cbd5e1\" font-size=\"7.5\">• Enrutadores de intención (Routing)</text>\n    <text x=\"16\" y=\"138\" fill=\"#cbd5e1\" font-size=\"7.5\">• Extracción estructurada JSON rápida</text>\n    <text x=\"16\" y=\"152\" fill=\"#cbd5e1\" font-size=\"7.5\">• Moderación y scoring en tiempo real</text>\n    <text x=\"16\" y=\"164\" fill=\"#cbd5e1\" font-size=\"7.5\">• Agentes ligeros de alto volumen</text>\n  </g>\n\n  <!-- Model 2: Sonnet 3.5 (The Flagship) -->\n  <g transform=\"translate(235, 38)\">\n    <rect width=\"210\" height=\"180\" rx=\"6\" fill=\"#111c33\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n    <rect width=\"210\" height=\"26\" rx=\"6\" fill=\"#0369a1\"/>\n    <text x=\"12\" y=\"17\" fill=\"#ffffff\" font-size=\"10\" font-weight=\"800\">CLAUDE 3.5 SONNET</text>\n    <text x=\"145\" y=\"17\" fill=\"#bae6fd\" font-size=\"8.5\" font-weight=\"700\">Insignia / Core</text>\n\n    <text x=\"12\" y=\"42\" fill=\"#cbd5e1\" font-size=\"8.5\" font-weight=\"700\">Métricas Clave:</text>\n    <text x=\"12\" y=\"56\" fill=\"#94a3b8\" font-size=\"8\">• Máximo rendimiento en Coding</text>\n    <text x=\"12\" y=\"70\" fill=\"#94a3b8\" font-size=\"8\">• Salida máxima: 8.192 tokens</text>\n    <text x=\"12\" y=\"84\" fill=\"#94a3b8\" font-size=\"8\">• Visión multimodal de vanguardia</text>\n\n    <rect x=\"10\" y=\"96\" width=\"190\" height=\"74\" rx=\"4\" fill=\"#0f172a\" stroke=\"#0284c7\"/>\n    <text x=\"16\" y=\"110\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"700\">Casos de Uso Ideales:</text>\n    <text x=\"16\" y=\"124\" fill=\"#cbd5e1\" font-size=\"7.5\">• Generación y refactorización de código</text>\n    <text x=\"16\" y=\"138\" fill=\"#cbd5e1\" font-size=\"7.5\">• Agentes autónomos multi-herramienta</text>\n    <text x=\"16\" y=\"152\" fill=\"#cbd5e1\" font-size=\"7.5\">• Análisis de diagramas de arquitectura</text>\n    <text x=\"16\" y=\"164\" fill=\"#cbd5e1\" font-size=\"7.5\">• Razonamiento técnico y científico</text>\n  </g>\n\n  <!-- Model 3: Opus 3 -->\n  <g transform=\"translate(460, 38)\">\n    <rect width=\"205\" height=\"180\" rx=\"6\" fill=\"#111c33\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n    <rect width=\"205\" height=\"26\" rx=\"6\" fill=\"#78350f\"/>\n    <text x=\"12\" y=\"17\" fill=\"#fef3c7\" font-size=\"10\" font-weight=\"800\">CLAUDE 3 OPUS</text>\n    <text x=\"135\" y=\"17\" fill=\"#fde68a\" font-size=\"8.5\" font-weight=\"700\">Profundidad</text>\n\n    <text x=\"12\" y=\"42\" fill=\"#cbd5e1\" font-size=\"8.5\" font-weight=\"700\">Métricas Clave:</text>\n    <text x=\"12\" y=\"56\" fill=\"#94a3b8\" font-size=\"8\">• Máxima abstracción conceptual</text>\n    <text x=\"12\" y=\"70\" fill=\"#94a3b8\" font-size=\"8\">• Salida máxima: 4.096 tokens</text>\n    <text x=\"12\" y=\"84\" fill=\"#94a3b8\" font-size=\"8\">• Análisis denso sin límite de tiempo</text>\n\n    <rect x=\"10\" y=\"96\" width=\"185\" height=\"74\" rx=\"4\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"16\" y=\"110\" fill=\"#fbbf24\" font-size=\"8\" font-weight=\"700\">Casos de Uso Ideales:</text>\n    <text x=\"16\" y=\"124\" fill=\"#cbd5e1\" font-size=\"7.5\">• Auditoría jurídica de contratos largos</text>\n    <text x=\"16\" y=\"138\" fill=\"#cbd5e1\" font-size=\"7.5\">• Síntesis densa de investigación</text>\n    <text x=\"16\" y=\"152\" fill=\"#cbd5e1\" font-size=\"7.5\">• Razonamiento filosófico y ético</text>\n    <text x=\"16\" y=\"164\" fill=\"#cbd5e1\" font-size=\"7.5\">• Consultoría estratégica compleja</text>\n  </g>\n</svg>",
